import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·33","description":"易小帖 - 卷五·33","frontmatter":{"title":"卷五·33","description":"易小帖 - 卷五·33"},"headers":[],"relativePath":"classics/yixiaotie/155.md","filePath":"classics/yixiaotie/155.md"}'),o={name:"classics/yixiaotie/155.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·33",tabindex:"-1"},[r("卷五·33 "),e("a",{class:"header-anchor",href:"#卷五·33","aria-label":"Permalink to “卷五·33”"},"​")],-1),e("p",null,"盛唐曰：《周易》有三易序，易用轉易分經用對易。其對易取六子化體，如鹹恆既未濟為首尾卦，以上四對下八而兩篇五十二卦，陰陽各對，無有畸零，固已發前聖所未發矣。然其功莫大於推易。嘗細細領會詳究始末，輒如接文孔，謦欬於在前，始而憬然，又既而爽然，又既則愉快愧悔不可名狀。蓋漢魏以還，學者失師承久矣，自八比行世，率泥於功令，間有異義，如馬鄭荀虞諸說，輒變色搖手，充塞兩耳，比聞父母之過尤甚。縱有闡精微以紹三聖，如推易法，而皆睥睨不一顧。向時朱駮《程傳》以為只說得一理，於《本義》不相合，然其作《本義》則又不推原始，不詳比例，不觀參互，轉側不善，觸類引伸，是仍一呺然廓落之理而已。即間及往來上下，或只據單卦，如十闢之一，而不知其他。或泛引別卦，如需訟非類聚，既未本群分而來，而多雜至，若順文說理，罔諦前後，剛柔得中，鑿稱五二，陽奇陰偶，即名當位，豖負塗曰見汚，車載鬼曰無有，失前禽曰開一面，田獲狐曰去媚邪，由不曉居方辨物，類聚群分之秘，而斤斤說理，理那得該。履五何為，夬同人何為，遇自道何自，頤豫何由，謙大畜無坎體而何川利涉，困三上皆陰爻而何妻不見，厥宗何宗，渙群何群，月何而望，日何而昃，雨何而虧，雲何而密，何一握為笑，而謬誤一班。何革言三就，而渾沌已審，果十分之格乎。曳翻之看乎。小時蒙師授易，講義寓目即能通曉，如看《論語》、《孟子》不異，凡六十四卦三百八十四爻，盡得臚而數之，曰某卦何雲，某爻何雲。及於揲筮所得，不過如神廟籖詩，吉凶早定，確不可移。所謂屢遷變動者安在。雖若春秋史傳，發繇布辭，洞如觀火，曠如發矇者，鮮不目為誕漫不經，為緣飾附會，是《周易》不亡於後世，而亡於人心。不亡於人心，而亡於謬說流傳，正義晦蔑。夫易道難窮，聖人韋編三絶尚蘄假年。末學小子，乾祿鄙夫，談何容易。曩者侍坐艾堂，吾師曾舉坤屯二卦，而說其大義，憷然於心。既讀《仲氏易》，反覆研尋，累日不能了數捲，自恨根鈍智昏，不得與聞斯道。已再發憤，苦力研索，遂稍稍達其條理。一日至讀得十數捲，大哉推易，由聚而分，因移而辨，屢易而終不易，凡焦贛，康成，範賢，侯果，虞翻知之不盡者，悉演之而系之，神明默成。蓋三聖在天，百世以俟，非偶然也。或曰：推移變化，抑又何常東家之東即西家之西，非株兔筌魚則邊獐邊鹿耳。是不知，率辭而揆方者也，夫東西無定，立則有定。獐鹿鶻突，左右可鶻突耶。泉從石冷，風自花香，銅山遙崩，洛鐘近應。公父文伯薄長者而厚婦人母言之賢而婦言之妬。宋富人牆壞，有盜，其子見智而鄰父見疑。試觀推易，屬詞有一句一字無著落者耶？有理障義閡不具神解者耶？或曰：君子引而不發，若茲之推，一卦而受數卦之來，一爻而具數子之象，而且卦背有錯有伏，有坎離正位，六畫有互有倒，有大象，首尾有環，上下往來以經之，廣陳卦象以緯之，語不傷盡乎哉。不知聖人嘗雲爾矣。書不盡言，言不盡意，生生之謂易，往來不窮謂之通，二篇之策萬有一千五百二十，當萬物之數。則吾師推易，象其物宜，觀其會通，摩之盪之，擬之議之，猶引端焉耳。昔元仁宗朝限《程傳》，《本義》取士，而盡去漢易，猶有曰：我治漢易不過不得科第耳，況三易之旨，發自文孔，而茫然不曉。則大經淪沒，終古聾瞶，將虛生浪死，不止不取科第矣。至若王輔嗣獨標清議，世競宗之，浸淫流潰，範甯謂弼罪浮桀紂。夫弼尚罪浮桀紂，況宗弼者耶。然則吾師之功，何如乎。讀者思之。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
